def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    divider = 2

    # Locate the full straight divider.
    line = next((("h", r) for r in range(h)
                 if all(g[r][c] == divider for c in range(w))), None)
    if line is None:
        line = next((("v", c) for c in range(w)
                     if all(g[r][c] == divider for r in range(h))), None)
    if line is None:
        return g

    from collections import Counter
    counts = Counter(v for row in g for v in row if v != divider)
    if not counts:
        return g
    background = counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] not in (divider, background)]
    if not points:
        return g

    # Slide the marked shape up against the divider; leave a full 8 stripe
    # immediately beyond the shape's far edge.
    orientation, pos = line
    if orientation == "h":
        below = sum(r for r, c in points) / len(points) > pos
        dr = (pos + 1 - min(r for r, c in points)) if below else (pos - 1 - max(r for r, c in points))
        moved = [(r + dr, c, g[r][c]) for r, c in points]
        for r, c in points:
            g[r][c] = background
        for r, c, color in moved:
            g[r][c] = color
        far = max(r for r, c, color in moved) + 1 if below else min(r for r, c, color in moved) - 1
        if 0 <= far < h:
            g[far] = [8] * w
    else:
        right = sum(c for r, c in points) / len(points) > pos
        dc = (pos + 1 - min(c for r, c in points)) if right else (pos - 1 - max(c for r, c in points))
        moved = [(r, c + dc, g[r][c]) for r, c in points]
        for r, c in points:
            g[r][c] = background
        for r, c, color in moved:
            g[r][c] = color
        far = max(c for r, c, color in moved) + 1 if right else min(c for r, c, color in moved) - 1
        if 0 <= far < w:
            for r in range(h):
                g[r][far] = 8
    return g
